async function buildSystemPrompt(app, settings) {
    const loaded = [];
    const skipped = [];
    const parts = [];
    let total = 0;
    const cap = 60000;
    for (const p of settings.rulesPaths) {
        const f = app.vault.getAbstractFileByPath(p);
        if (f instanceof obsidian.TFile && f.extension === "md") {
            let content = "";
            try {
                content = await app.vault.cachedRead(f);
            }
            catch (e) {
                skipped.push(p + "(读取失败)");
                continue;
            }
            if (total + content.length > cap) {
                skipped.push(p + "(超长截断)");
                continue;
            }
            parts.push("===== 规则文档:" + p + " =====\n" + content);
            total += content.length;
            loaded.push(p);
        }
        else {
            skipped.push(p);
        }
    }
    const system = [
        "你是「VaultCurator」,一个运行在 Obsidian 知识库中的 AI 助手,遵循以下规则执行任务。",
        "当前 vault 的规则如下。所有任务必须先理解并遵守,再执行。",
        parts.join("\n\n"),
        SAFETY_NET,
        "执行任务时请优先增量更新,不要重复造轮子;输出格式严格按照任务要求。",
    ].join("\n\n");
    return { system, loaded, skipped };
}

const EXCLUDE_DIRS = new Set([".obsidian", ".claudian", ".git", ".trash"]);
function isExcluded(p) {
    return p.split("/").some((s) => EXCLUDE_DIRS.has(s));
}
function parseFrontmatter(content) {
    const norm = content.replace(/\r\n/g, "\n");
    if (!norm.startsWith("---\n"))
        return { fields: {}, hasFrontmatter: false };
    const end = norm.indexOf("\n---\n", 4);
    if (end < 0)
        return { fields: {}, hasFrontmatter: false };
    const block = norm.slice(4, end);
    const fields = {};
    for (const line of block.split("\n")) {
        const m = /^([\w\u4e00-\u9fa5-]+):\s*(.*)$/.exec(line);
        if (m)
            fields[m[1].trim()] = m[2].trim();
    }
    return { fields, hasFrontmatter: true };
}
function extractWikiLinks(content) {
    const out = [];
    const re = /\[\[([^\]|#]+)(?:[#|][^\]]*)?\]\]/g;
    let m;
    while ((m = re.exec(content)) !== null) {
        const target = m[1].trim();
        if (target)
            out.push(target);
    }
    return out;
}
function countHighlights(content) {
    const re = /==([^=\n]+)==/g;
    const samples = [];
    let total = 0;
    let m;
    while ((m = re.exec(content)) !== null) {
        // 反引号代码跨度内的 ==...== 是说明文字,不算高亮
        const before = m.index > 0 ? content[m.index - 1] : "";
        const after = m.index + m[0].length < content.length ? content[m.index + m[0].length] : "";
        if (before === "`" || after === "`")
            continue;
        total++;
        if (samples.length < 5)
            samples.push(m[1].trim().slice(0, 60));
    }
    return { count: total, samples };
}
