                if (app.vault.getAbstractFileByPath(entry.path))
                    return "源路径已存在,无法移回:" + entry.path;
                await app.fileManager.renameFile(t, entry.path);
                await recordRollback(app, entry, "移动(回滚) " + target + " → " + entry.path);
