        const hlTotal = stats.highlights.reduce((a, h) => a + h.count, 0);
        new obsidian.Notice("扫描完成:md " + stats.totalMd + " 个,新增/更新 " + stats.newOrUpdated.length + " 个,高亮疑问 " + hlTotal + " 处");
