            const est = formatCostEstimate(input.inputTokens, this.settings.maxTokens, this.settings.model);
            const ok = await confirmDialog(this.app, "一键整理(只读)", "预计输入 " + input.inputTokens.toLocaleString() + " tokens\n" + est + "\n\n调用 DeepSeek 生成增量整理建议?\n本操作只读,不修改任何文件。");
